import type { RecruitmentChannel, RecruitmentChannelStrategy } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';
import { MailIcon, MessageSquareIcon } from 'lucide-vue-next';

interface ChannelStrategyEntry {
  label: string;
  touchPhrase: string;
}

interface ChannelEntry {
  label: string;
  variant: BadgeVariants;
  icon: typeof MailIcon;
}

export const channelConfig: Record<RecruitmentChannel, ChannelEntry> = {
  email: { label: 'Email', variant: 'info', icon: MailIcon },
  sms: { label: 'SMS', variant: 'success', icon: MessageSquareIcon },
};

export function getChannel(channel: RecruitmentChannel): ChannelEntry {
  return channelConfig[channel] ?? { label: snakeCaseToCapitalizedCase(channel), variant: 'default', icon: MailIcon };
}

export const channelOptions: SelectItem<RecruitmentChannel>[] = Object.entries(channelConfig).map(
  ([value, { label }]) => ({ name: label, value: value as RecruitmentChannel })
);

export const channelStrategyConfig: Record<RecruitmentChannelStrategy, ChannelStrategyEntry> = {
  email_only: { label: 'Email only', touchPhrase: '1 email' },
  sms_only: { label: 'SMS only', touchPhrase: '1 text' },
  sms_else_email: {
    label: 'SMS with email fallback',
    touchPhrase: '1 text, or 1 email when they cannot be texted',
  },
  alternating: {
    label: 'Alternating SMS & email',
    touchPhrase: '1 message, alternating between text and email each time',
  },
  sms_and_email: { label: 'SMS & email together', touchPhrase: '1 email and 1 text' },
};

export function getChannelStrategy(strategy: RecruitmentChannelStrategy): ChannelStrategyEntry {
  return channelStrategyConfig[strategy] ?? { label: snakeCaseToCapitalizedCase(strategy), touchPhrase: '1 message' };
}

export const channelStrategyValues = Object.keys(channelStrategyConfig) as [
  RecruitmentChannelStrategy,
  ...RecruitmentChannelStrategy[],
];

export const channelStrategyOptions: SelectItem<RecruitmentChannelStrategy>[] = Object.entries(
  channelStrategyConfig
).map(([value, { label }]) => ({ name: label, value: value as RecruitmentChannelStrategy }));
